def toposort(nodes: list[int], edges: list[tuple[int, int]]) -> list[int]:
    if not nodes:
        return []

    indeg = {node: 0 for node in nodes}
    adj = {}

    for u, v in edges:
        if u == v:
            raise ValueError
        if u in adj:
            neighbors = adj[u]
        else:
            neighbors = set()
            adj[u] = neighbors
        if v not in neighbors:
            neighbors.add(v)
            indeg[v] += 1

    ready = [node for node in nodes if indeg[node] == 0]
    ready.sort()
    order = []

    while ready:
        u = ready[0]
        last = ready.pop()
        if ready:
            ready[0] = last
            parent = 0
            size = len(ready)
            while True:
                left = parent * 2 + 1
                if left >= size:
                    break
                right = left + 1
                child = right if right < size and ready[right] < ready[left] else left
                if ready[parent] <= ready[child]:
                    break
                ready[parent], ready[child] = ready[child], ready[parent]
                parent = child
        order.append(u)

        for v in adj.get(u, ()):
            indeg[v] -= 1
            if indeg[v] == 0:
                ready.append(v)
                child = len(ready) - 1
                while child > 0:
                    parent = (child - 1) // 2
                    if ready[parent] <= ready[child]:
                        break
                    ready[parent], ready[child] = ready[child], ready[parent]
                    child = parent

    if len(order) != len(nodes):
        raise ValueError
    return order
